(()=>{const hero=document.querySelector('#wdl01-hero');if(!hero)return;document.querySelectorAll('[data-lock-finish]').forEach(b=>b.addEventListener('click',()=>{const finish=b.dataset.lockFinish;hero.src='/assets/wdl01/wdl01-'+finish+'.jpg';hero.alt='WDL01 '+finish+' WiFi smart mortise door lock indoor and outdoor panels';document.querySelectorAll('[data-lock-finish]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}))})();